<template><div class="app-container"><el-page-header @back="router.back()" :content="`${combination.combinationName || '函数组合'} - 综合图表`"/><div class="toolbar"><span>{{ combination.description || '组合函数综合展示' }}</span><el-checkbox v-for="layer in layers" :key="layer.id" v-model="layer.visible" @change="render">{{ layer.name }}</el-checkbox></div><div ref="chartRef" class="chart"/></div></template>
<script setup name="FunctionCombinationChart">import * as echarts from 'echarts';import { useRoute, useRouter } from 'vue-router';import { listCombination } from '@/api/project-research/combination';import { getFunctionVisualData, listFunction } from '@/api/project-research/function'
const route=useRoute(),router=useRouter(),chartRef=ref(),combination=ref({}),layers=ref([]);let chart
function render(){const base=layers.value.find(x=>x.data)?.data;if(!chart||!base)return;const points=[],areas=[];layers.value.filter(x=>x.visible&&x.data?.indicator).forEach(layer=>layer.data.indicator.forEach((item,i)=>{if(layer.name==='swing_highs_lows'&&item.highLow&&base.rows[i])points.push({value:item.highLow>0?'高点':'低点',coord:[i,item.highLow>0?base.rows[i].high:base.rows[i].low],itemStyle:{color:item.highLow>0?'#dc2626':'#16a34a'}});if(['fvg','ob'].includes(layer.name)&&base.rows[i])areas.push([{xAxis:i,yAxis:base.rows[i].low},{xAxis:Math.min(item.mitigatedIndex||base.rows.length-1,base.rows.length-1),yAxis:base.rows[i].high}])}));chart.setOption({animation:false,tooltip:{trigger:'axis'},dataZoom:[{type:'inside'},{type:'slider'}],xAxis:{type:'category',data:base.rows.map(x=>x.time),axisLabel:{show:false}},yAxis:{scale:true},series:[{type:'candlestick',name:'BTC',data:base.rows.map(x=>[x.open,x.close,x.low,x.high]),markPoint:points.length?{data:points,symbolSize:14}:undefined,markArea:areas.length?{itemStyle:{color:'rgba(59,130,246,.12)'},data:areas}:undefined}]},true);chart.resize()}
async function load(){const id=Number(route.query.id);const [c,f]=await Promise.all([listCombination({pageNum:1,pageSize:1000}),listFunction({pageNum:1,pageSize:1000})]);combination.value=c.rows.find(x=>x.id===id)||{};const funcs=f.rows;layers.value=(combination.value.functionIds||[]).map(fid=>{const fn=funcs.find(x=>x.id===fid);return{id:fid,name:fn?.funcName||`函数${fid}`,visible:true,data:null}});chart=echarts.init(chartRef.value);await Promise.all(layers.value.map(async layer=>{try{const fn=funcs.find(x=>x.id===layer.id);layer.data=(await getFunctionVisualData(layer.id,fn?.funcName)).data}catch{}}));render()}onMounted(load);onBeforeUnmount(()=>chart?.dispose())</script><style scoped>.toolbar{display:flex;align-items:center;gap:18px;margin:18px 0;color:var(--el-text-color-secondary)}.chart{height:calc(100vh - 190px);min-height:560px;width:100%}</style>
